// Preparar o relatório com todos os findings da avaliação
const report = {
  timestamp: new Date().toISOString(),
  model: "govbr-eval-2026",
  appUrl: "http://localhost:3000/fluxo.html",
  scope: ["Interface completa de login do gov.br"],
  notes: "Varredura completa da página de login. Avaliação incluiu: análise de tokens (cores, espaçamentos, tipografia), estrutura de componentes (button, input, divider, item, list, tag), e testes de acessibilidade com axe-core. Interações testadas: foco e preenchimento do campo CPF. Axe passou com 36 verificações em estado inicial e após interações.",
  findings: [
    {
      selector: "#root > main > section:nth-of-type(2) > div:nth-of-type(2)",
      relatedSelectors: [],
      rule: "ds-token-color",
      description: "border-color: rgb(222, 226, 230) (#dee2e6) não corresponde a nenhum token do DS. Cor mais próxima seria --gray-cool-10 (#dfe1e2). Cores arbitrárias quebram a identidade visual e o theming do padrão."
    },
    {
      selector: "#root > main > section:nth-of-type(2) > div:nth-of-type(2) > div:nth-of-type(1)",
      relatedSelectors: [],
      rule: "ds-token-spacing",
      description: "padding: 13px está fora da escala tipográfica do DS. Espaçamentos devem ser múltiplos de 4px conforme escala do DS (8px, 12px, 16px, 20px, etc)."
    },
    {
      selector: "#root > main > section:nth-of-type(2) > div:nth-of-type(2) > div:nth-of-type(2)",
      relatedSelectors: [],
      rule: "ds-token-spacing",
      description: "padding: 13px está fora da escala tipográfica do DS. Espaçamentos devem ser múltiplos de 4px conforme escala do DS (8px, 12px, 16px, 20px, etc)."
    },
    {
      selector: "#root > main > section:nth-of-type(2) > div:nth-of-type(2) > div:nth-of-type(3)",
      relatedSelectors: [],
      rule: "ds-token-spacing",
      description: "padding: 13px está fora da escala tipográfica do DS. Espaçamentos devem ser múltiplos de 4px conforme escala do DS (8px, 12px, 16px, 20px, etc)."
    },
    {
      selector: "#root > main > section:nth-of-type(2) > div:nth-of-type(2) > div:nth-of-type(4)",
      relatedSelectors: [],
      rule: "ds-token-spacing",
      description: "padding: 13px está fora da escala tipográfica do DS. Espaçamentos devem ser múltiplos de 4px conforme escala do DS (8px, 12px, 16px, 20px, etc)."
    },
    {
      selector: "#cpf",
      relatedSelectors: [],
      rule: "ds-structure-input-tag",
      description: "br-input está aplicado diretamente ao elemento <input>. Conforme exemplos oficiais do gov.br DS, a classe br-input deve ser aplicada a <div> que envolve o input. A estrutura atual diverge do padrão canônico."
    }
  ]
};

// Fazer POST do relatório
const response = await fetch('/api/save-flow-results', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(report)
});

const result = await response.json();
console.log('POST Response:', result);
console.log('Status:', response.status);
